-- CreateIndex
CREATE UNIQUE INDEX "mfa_recovery_codes_code_hash_key" ON "mfa_recovery_codes"("code_hash");

-- CreateIndex
CREATE INDEX "mfa_recovery_codes_user_id_idx" ON "mfa_recovery_codes"("user_id");

-- AddForeignKey
ALTER TABLE "mfa_factors" ADD CONSTRAINT "mfa_factors_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "mfa_recovery_codes" ADD CONSTRAINT "mfa_recovery_codes_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- =============================================================================================
-- Hand-written below this line: ciphertexts are versioned (v1:<iv>:<tag>:<data>, base64url);
-- the accepted time step only moves forward; recovery code hashes are SHA-256 hex, used once.
-- Factors and codes may be deleted (turning MFA off or replacing codes); every change is audited
-- by the application. See docs/adr/0005-built-in-authentication.md.
-- =============================================================================================

ALTER TABLE "mfa_factors" ADD CONSTRAINT "mfa_factors_shape"
  CHECK ("secret_ciphertext" ~ '^v1:[A-Za-z0-9_-]+:[A-Za-z0-9_-]+:[A-Za-z0-9_-]+$'
         AND ("last_used_step" IS NULL OR "last_used_step" > 0));

CREATE FUNCTION app_mfa_factor_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."last_used_step" IS NOT NULL AND (NEW."last_used_step" IS NULL OR NEW."last_used_step" <= OLD."last_used_step") THEN
    RAISE EXCEPTION 'a code cannot be used twice' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."confirmed_at" IS NOT NULL AND NEW."secret_ciphertext" IS DISTINCT FROM OLD."secret_ciphertext" THEN
    RAISE EXCEPTION 'turn MFA off before replacing a confirmed factor' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "mfa_factors_guard"
  BEFORE UPDATE ON "mfa_factors"
  FOR EACH ROW EXECUTE FUNCTION app_mfa_factor_guard();

ALTER TABLE "mfa_recovery_codes" ADD CONSTRAINT "mfa_recovery_codes_hash"
  CHECK ("code_hash" ~ '^[0-9a-f]{64}$');

CREATE FUNCTION app_mfa_recovery_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."used_at" IS NOT NULL OR (NEW."user_id", NEW."code_hash") IS DISTINCT FROM (OLD."user_id", OLD."code_hash") THEN
    RAISE EXCEPTION 'a recovery code is used once' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "mfa_recovery_codes_guard"
  BEFORE UPDATE ON "mfa_recovery_codes"
  FOR EACH ROW EXECUTE FUNCTION app_mfa_recovery_guard();

REVOKE ALL ON "mfa_factors", "mfa_recovery_codes" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE, DELETE ON "mfa_factors", "mfa_recovery_codes" TO veyra_app;
